   * Restores the heap property by moving the entry at `pos` upward.
   * @param {number} pos Starting position.
   * @returns {void}
   */
  #siftUp(pos) {
    let i = pos;
    while (i > 0) {
      const parent = (i - 1) >> 1;
      if (this.#before(this.#items[i], this.#items[parent])) {
        this.#swap(i, parent);
        i = parent;
      } else break;
    }
