   * Restores the heap property by moving the entry at `pos` downward.
   * @param {number} pos Starting position.
   * @returns {void}
   */
  #siftDown(pos) {
    const items = this.#items;
    let i = pos;
    for (;;) {
      const left = 2 * i + 1;
      const right = 2 * i + 2;
      let smallest = i;
      if (left < items.length && this.#before(items[left], items[smallest])) smallest = left;
      if (right < items.length && this.#before(items[right], items[smallest])) smallest = right;
      if (smallest === i) break;
      this.#swap(i, smallest);
      i = smallest;
